insert into private.training_questions(
 code,bank_type,skill_code,difficulty,question_en,question_zh,options_en,options_zh,
 correct_index,explanation_en,explanation_zh,active,is_test,source_version
) values
('D-C-01','daily','CLOSING',1,'After sending an official quote, what is the Agent''s next sales responsibility?','发送正式报价后，Agent 下一项销售责任是什么？','["Follow up clearly","Delete the lead","Wait forever","Collect money personally"]'::jsonb,'["明确跟进","删除线索","无限等待","私人收款"]'::jsonb,0,'A clear follow-up keeps the customer moving toward confirmation.','明确跟进能推动客户完成确认。',true,true,'phase3-test-v1'),
('D-C-02','daily','CLOSING',2,'What should a closing message make clear?','成交信息应该让客户清楚什么？','["The next confirmation or payment step","A hidden discount","Another Agent''s commission","Internal cost details"]'::jsonb,'["下一步确认或付款方式","隐藏折扣","其他 Agent 的佣金","内部成本资料"]'::jsonb,0,'Closing should reduce uncertainty by stating the next approved action.','成交信息应明确下一步批准动作，减少客户不确定性。',true,true,'phase3-test-v1'),
('D-LF-01','daily','LEAD-FINDING',1,'Which lead source should an Agent record when a customer came through a personal referral?','客户来自朋友介绍时，Agent 应记录哪个来源？','["Referral","Instagram","Corporate outreach","Other"]'::jsonb,'["转介绍","Instagram","企业开发","其他"]'::jsonb,0,'Use the actual acquisition source so later conversion reporting stays accurate.','按真实获客来源记录，后续转化数据才准确。',true,true,'phase3-test-v1'),
('D-LF-02','daily','LEAD-FINDING',2,'What should happen before treating a social-media enquiry as a qualified lead?','把社媒询问视为合格线索前，应该先做什么？','["Confirm budget, occasion and date","Promise an exact design","Ask for private payment","Skip customer details"]'::jsonb,'["确认预算、场合和日期","承诺完全复刻设计","要求私下付款","跳过客户资料"]'::jsonb,0,'Qualification requires the basic buying context before the lead moves forward.','合格线索需要先确认基本购买情境。',true,true,'phase3-test-v1'),
('D-O-01','daily','OBJECTION',1,'A customer says the quote is too expensive. What should the Agent do first?','客户说报价太贵，Agent 首先应该怎么做？','["Clarify budget and offer approved options","Secretly discount it","Argue with the customer","Change the invoice manually"]'::jsonb,'["确认预算并提供批准方案","私下打折","和客户争论","手动改发票"]'::jsonb,0,'Price objections should be handled through approved options, not unauthorized discounts.','价格异议应通过批准方案处理，不能私自折扣。',true,true,'phase3-test-v1'),
('D-O-02','daily','OBJECTION',2,'Which response protects company margin when a customer wants a lower price?','客户要求更低价格时，哪种做法能保护公司毛利？','["Adjust scope through approved options","Keep scope and cut price privately","Remove payment records","Promise free extras"]'::jsonb,'["通过批准方案调整范围","保持范围但私下降价","删除付款记录","承诺免费加料"]'::jsonb,0,'Change scope or option within approved pricing rather than bypassing the guard.','应在批准定价内调整范围或方案，不能绕过利润保护。',true,true,'phase3-test-v1'),
('D-P-01','daily','PAYMENT',1,'Where should a customer make payment?','客户应该在哪里付款？','["EW VERDORA official payment channel","Agent personal account","Any friend''s account","Cash without record"]'::jsonb,'["EW VERDORA 官方付款渠道","Agent 私人账户","朋友账户","无记录现金"]'::jsonb,0,'Payments must stay on the official company channel.','付款必须通过公司官方渠道。',true,true,'phase3-test-v1'),
('D-P-02','daily','PAYMENT',2,'When should an Agent treat an order as paid?','Agent 什么时候可以把订单视为已付款？','["After the official system records payment","When the customer says ''done''","After a screenshot only","Before payment to save time"]'::jsonb,'["官方系统记录付款后","客户口头说已付","只有截图时","为了省时间先标已付"]'::jsonb,0,'The official payment record is the trusted source of payment status.','应以官方付款记录作为付款状态依据。',true,true,'phase3-test-v1'),
('D-Q-01','daily','QUALIFY',1,'Which three details are essential to qualify a flower order first?','花艺订单最先需要确认哪三项？','["Budget, occasion, delivery date","Favorite color, age, job","Follower count, device, postcode","Card font, music, parking"]'::jsonb,'["预算、场合、送达日期","喜欢的颜色、年龄、职业","粉丝数、设备、邮编","卡片字体、音乐、停车"]'::jsonb,0,'Budget, occasion and delivery date define the core requirement.','预算、场合和送达日期构成核心需求。',true,true,'phase3-test-v1'),
('D-Q-02','daily','QUALIFY',2,'A customer has not confirmed delivery timing. What is the safest next step?','客户尚未确认送达时间，最安全的下一步是什么？','["Ask for a delivery window","Invent a time","Mark it delivered","Take private payment"]'::jsonb,'["询问送达时间段","自行决定时间","标记已送达","私下收款"]'::jsonb,0,'The Agent should confirm a usable delivery window instead of guessing.','Agent 应确认可执行的送达时间段，不能猜。',true,true,'phase3-test-v1'),
('D-R-01','daily','REFERENCE',1,'What does a reference image mean in the quoting flow?','报价流程里的参考图代表什么？','["A direction to assess and adapt","A guaranteed exact replica","Permission to ignore budget","Automatic payment approval"]'::jsonb,'["用于评估和调整的方向","保证完全复刻","可以忽略预算","自动批准付款"]'::jsonb,0,'A reference guides assessment; it is not automatically an exact-replica promise.','参考图用于评估，不等于自动承诺完全复刻。',true,true,'phase3-test-v1'),
('D-R-02','daily','REFERENCE',2,'Who should decide the official price after a reference image is submitted?','提交参考图后，正式价格应由谁决定？','["The approved server quote flow","The Agent''s own estimate","The customer alone","A random percentage"]'::jsonb,'["系统批准的报价流程","Agent 自己估价","只由客户决定","随机百分比"]'::jsonb,0,'Official pricing must come from the approved server-side quote process.','正式价格必须来自系统批准的服务器报价流程。',true,true,'phase3-test-v1'),
('E-01','exam','LEAD-FINDING',1,'Which source label best fits a repeat customer?','回头客最适合记录为哪个来源？','["Previous customer","Referral","Threads","Other"]'::jsonb,'["老客复购","转介绍","Threads","其他"]'::jsonb,0,'Repeat buyers should use the previous-customer source.','回头客应使用老客复购来源。',true,true,'phase3-test-v1'),
('E-02','exam','QUALIFY',1,'Which missing detail blocks reliable delivery planning?','缺少哪项资料会影响可靠配送安排？','["Delivery date","Emoji choice","Phone wallpaper","Agent nickname"]'::jsonb,'["送达日期","Emoji 选择","手机壁纸","Agent 昵称"]'::jsonb,0,'A delivery date is operationally required.','送达日期是执行配送所需资料。',true,true,'phase3-test-v1'),
('E-03','exam','REFERENCE',1,'A reference image should be treated as what?','参考图应该被视为什么？','["Design direction","Exact guarantee","Payment receipt","Commission proof"]'::jsonb,'["设计方向","完全复刻保证","付款收据","佣金证明"]'::jsonb,0,'Reference images guide quoting and adaptation.','参考图用于报价和调整方向。',true,true,'phase3-test-v1'),
('E-04','exam','OBJECTION',1,'What is unauthorized when handling a price objection?','处理价格异议时，哪项是不允许的？','["Private discount outside approved pricing","Clarifying budget","Offering an approved option","Explaining scope"]'::jsonb,'["绕过批准定价私下降价","确认预算","提供批准方案","解释范围"]'::jsonb,0,'Agents must not bypass approved pricing.','Agent 不得绕过批准定价。',true,true,'phase3-test-v1'),
('E-05','exam','CLOSING',1,'What is the best purpose of a follow-up?','跟进最主要的目的是什么？','["Move the customer to a clear next step","Pressure endlessly","Reveal internal cost","Discuss another Agent"]'::jsonb,'["推动客户进入明确下一步","无限施压","透露内部成本","讨论其他 Agent"]'::jsonb,0,'Follow-up should make progress actionable.','跟进应让下一步变得可执行。',true,true,'phase3-test-v1'),
('E-06','exam','PAYMENT',1,'Which payment route is allowed?','哪种付款方式是允许的？','["Official EW VERDORA channel","Agent personal bank","Friend''s wallet","Unrecorded cash"]'::jsonb,'["EW VERDORA 官方渠道","Agent 私人银行","朋友电子钱包","无记录现金"]'::jsonb,0,'Official channels protect both customer and company.','官方渠道同时保护客户与公司。',true,true,'phase3-test-v1'),
('E-07','exam','LEAD-FINDING',2,'Why record the true lead source?','为什么要记录真实线索来源？','["To measure acquisition performance","To increase price secretly","To reveal customer data","To avoid follow-up"]'::jsonb,'["衡量获客表现","私自涨价","泄露客户资料","避免跟进"]'::jsonb,0,'Accurate sources support meaningful channel performance data.','准确来源才能产生有效渠道数据。',true,true,'phase3-test-v1'),
('E-08','exam','QUALIFY',2,'A customer gives only a budget. What still needs confirmation?','客户只给了预算，还需要确认什么？','["Occasion and delivery date","Agent commission","Internal profit","Other agents'' sales"]'::jsonb,'["场合和送达日期","Agent 佣金","内部利润","其他 Agent 销售"]'::jsonb,0,'Budget alone is insufficient for a usable order brief.','只有预算不足以形成可执行需求。',true,true,'phase3-test-v1'),
('E-09','exam','REFERENCE',2,'Who can release an official price?','谁可以释放正式报价？','["Approved server quote process","Any Agent manually","Any customer","Social media poll"]'::jsonb,'["批准的服务器报价流程","任何 Agent 手动决定","任何客户","社媒投票"]'::jsonb,0,'The server-side approved process owns official pricing.','正式报价由服务器批准流程产生。',true,true,'phase3-test-v1'),
('E-10','exam','OBJECTION',2,'If a lower budget cannot support the same scope, what should change?','较低预算无法支持原范围时，应调整什么？','["Approved scope or option","Payment records","Customer identity","Commission history"]'::jsonb,'["批准的范围或方案","付款记录","客户身份","佣金历史"]'::jsonb,0,'Scope can be adapted within approved options instead of unauthorized discounting.','应通过批准方案调整范围，而不是私下降价。',true,true,'phase3-test-v1'),
('E-11','exam','CLOSING',2,'Which follow-up is strongest?','哪种跟进方式最好？','["Specific and action-oriented","Vague and open-ended forever","Threatening","No message"]'::jsonb,'["具体并有明确行动","长期模糊开放","威胁式","完全不发"]'::jsonb,0,'A clear action-oriented follow-up reduces friction.','明确行动导向的跟进能减少阻力。',true,true,'phase3-test-v1'),
('E-12','exam','PAYMENT',2,'A payment screenshot arrives but the system is still pending. What status should the Agent trust?','客户发来付款截图，但系统仍显示 pending，Agent 应相信哪个状态？','["System payment status","Screenshot alone","Customer promise","Agent guess"]'::jsonb,'["系统付款状态","只看截图","客户口头保证","Agent 猜测"]'::jsonb,0,'The official system record controls payment status.','付款状态以官方系统记录为准。',true,true,'phase3-test-v1'),
('E-13','exam','LEAD-FINDING',2,'Which action helps turn an enquiry into a workable lead?','哪个动作能把询问变成可执行线索？','["Capture source and core need","Delete it immediately","Promise exact design first","Ask for private transfer"]'::jsonb,'["记录来源和核心需求","立即删除","先承诺完全复刻","要求私下转账"]'::jsonb,0,'Source plus core need creates a traceable lead.','来源加核心需求才能形成可追踪线索。',true,true,'phase3-test-v1'),
('E-14','exam','QUALIFY',2,'Why is a delivery window useful?','为什么送达时间段很重要？','["It makes fulfillment schedulable","It changes commission rate","It reveals cost","It replaces payment"]'::jsonb,'["让履约可排程","改变佣金率","泄露成本","替代付款"]'::jsonb,0,'A delivery window makes operations schedulable.','送达时间段让运营可排程。',true,true,'phase3-test-v1'),
('E-15','exam','REFERENCE',3,'What should never be inferred from a reference image alone?','仅凭参考图绝不能推断什么？','["An exact-replica commitment","A style direction","An occasion hint","A possible scale"]'::jsonb,'["完全复刻承诺","风格方向","场合线索","可能的规模"]'::jsonb,0,'Exact commitment requires approved handling, not assumption.','完全复刻不能仅凭参考图自行承诺。',true,true,'phase3-test-v1'),
('E-16','exam','OBJECTION',3,'What should remain protected during negotiation?','议价过程中必须保护什么？','["Approved pricing and margin rules","A secret personal discount","Another agent''s rank","Unrecorded payment"]'::jsonb,'["批准定价和毛利规则","秘密私人折扣","其他 Agent 排名","未记录付款"]'::jsonb,0,'Negotiation cannot bypass approved pricing controls.','议价不能绕过批准定价控制。',true,true,'phase3-test-v1'),
('E-17','exam','CLOSING',3,'What should happen after the customer agrees with the quote?','客户同意报价后，下一步应该是什么？','["Direct them to the official confirmation/payment step","Change the price privately","Share internal cost","Move off-platform"]'::jsonb,'["引导进入官方确认/付款步骤","私自改价","分享内部成本","转到私下交易"]'::jsonb,0,'Agreement should move into the official confirmation flow.','客户同意后应进入官方确认流程。',true,true,'phase3-test-v1'),
('E-18','exam','PAYMENT',3,'Why is off-platform payment prohibited?','为什么禁止私下付款？','["It bypasses official controls and records","It improves auditability","It guarantees delivery","It raises training score"]'::jsonb,'["会绕过官方控制和记录","会提升审计性","会保证送达","会提高训练分"]'::jsonb,0,'Off-platform payment breaks the controlled payment and audit trail.','私下付款会破坏受控付款和审计链。',true,true,'phase3-test-v1'),
('E-19','exam','QUALIFY',3,'Which brief is most ready for formal quoting?','哪份需求最适合进入正式报价？','["Budget + occasion + date/time + reference if available","Only a greeting","Only customer name","Only social handle"]'::jsonb,'["预算 + 场合 + 日期/时间 + 可用参考图","只有问候","只有客户名字","只有社媒账号"]'::jsonb,0,'A complete brief gives the quote process the information it needs.','完整需求让报价流程拥有所需资料。',true,true,'phase3-test-v1'),
('E-20','exam','REFERENCE',3,'What protects the Agent from overpromising a reference design?','什么能避免 Agent 对参考设计过度承诺？','["Use approved design commitment and server quote flow","Promise exact first","Ignore constraints","Quote from memory"]'::jsonb,'["使用批准的设计承诺和服务器报价流程","先承诺完全复刻","忽略限制","凭记忆报价"]'::jsonb,0,'Approved commitment rules and server quoting prevent overpromise.','批准的承诺规则和服务器报价能防止过度承诺。',true,true,'phase3-test-v1')
on conflict(code) do update set
 bank_type=excluded.bank_type,skill_code=excluded.skill_code,difficulty=excluded.difficulty,
 question_en=excluded.question_en,question_zh=excluded.question_zh,
 options_en=excluded.options_en,options_zh=excluded.options_zh,correct_index=excluded.correct_index,
 explanation_en=excluded.explanation_en,explanation_zh=excluded.explanation_zh,
 active=excluded.active,is_test=excluded.is_test,source_version=excluded.source_version,updated_at=now();
